# [ src/dialogs/ZA02_sod_court_and_strategy/trp_sod_strategy_advisor_plyr_sod_sa_after_5.py:L1-L3 ] trp_sod_strategy_advisor|plyr::sod_sa_after_5->sod_sa_after_6 [no_conditions] {the enemy will fear your pen more than your sword. the {var} can}
[trp_sod_strategy_advisor|plyr, "sod_sa_after_5", [], "The enemy will fear your pen more than your sword.  The {s5} cannot afford to lose your knowledge.  I will not deny you a warrior's death but I have another option.  Serve me on my council as my personal strategy advisor.  I will ensure your cup and bed is always filled with the ale or woman of your choice.  The time spent servicing my father away so many years away from our homeland will not be wasted.  More importantly, I offer you the revenge you desire against the Imperial Legion.", "sod_sa_after_6", []],
# [ src/dialogs/ZA02_sod_court_and_strategy/trp_sod_strategy_advisor_sod_sa_after_6.py:L1-L6 ] trp_sod_strategy_advisor::sod_sa_after_6->close_window [no_conditions] {my king, i will do this for you. but if the day comes you need a}
[trp_sod_strategy_advisor, "sod_sa_after_6", [], "My King, I will do this for you.  But if the day comes you need another blade, I will be ready.", "close_window", [
	(assign, "$g_sod_sa_in_court", 1),
	(party_remove_members, "p_main_party", "trp_sod_strategy_advisor", 1),
	]],
