[trp_sod_strategy_advisor|plyr, "sa_select_3_answer", [(this_or_next|is_between, "$g_sod_sa_talk_subject", 30, 40),(this_or_next|is_between, "$g_sod_sa_talk_subject", 20, 30),(is_between, "$g_sod_sa_talk_subject", 5, 10),], "General Overview.", "sa_select_general", []],
# [ src/dialogs/ZA02_sod_court_and_strategy/trp_sod_strategy_advisor_plyr_sa_select_3_answer_05.py:L1-L3 ] trp_sod_strategy_advisor|plyr::sa_select_3_answer->sa_select_noble [is_between] {tell me about their nobles.}
[trp_sod_strategy_advisor|plyr, "sa_select_3_answer", [(is_between, "$g_sod_sa_talk_subject", 20, 30),], "Tell me about their Nobles.", "sa_select_noble", []],
# [ src/dialogs/ZA02_sod_court_and_strategy/trp_sod_strategy_advisor_plyr_sa_select_3_answer_06.py:L1-L3 ] trp_sod_strategy_advisor|plyr::sa_select_3_answer->sa_select_melee_infantry [neg|is_between|neg|is_between] {tell me about their melee infantry.}
[trp_sod_strategy_advisor|plyr, "sa_select_3_answer", [(neg|is_between, "$g_sod_sa_talk_subject", 5, 10),(neg|is_between, "$g_sod_sa_talk_subject", 30, 37),], "Tell me about their Melee Infantry.", "sa_select_melee_infantry", []],
