# [ src/dialogs/ZZ99_misc_dialogs/anyone_plyr_loa_reaction_neg.py:L1-L3 ] anyone|plyr::loa_reaction_neg->loa_rejected [no_conditions] {{var}, begone! i have no time for this! you do not merit a place}
[anyone|plyr, "loa_reaction_neg", [], "{s1}, Begone!  I have no time for this!  You do not merit a place in my Kingdom!", "loa_rejected", []],
# [ src/dialogs/ZZ99_misc_dialogs/anyone_plyr_loa_accept.py:L1-L3 ] anyone|plyr::loa_accept->loa_swear_oath [no_conditions] {{var}, you have been an honorable foe and i tend to trust that t}
[anyone|plyr, "loa_accept", [], "{s1}, you have been an honorable foe and I tend to trust that this offer is genuine.", "loa_swear_oath", []],
# [ src/dialogs/ZB01_lords_politics_and_family/anyone_plyr_loa_swear_oath.py:L1-L3 ] anyone|plyr::loa_swear_oath->loa_swear_oath_2 [no_conditions] {kneel before me, {var}, and swear the following oath of fealty t}
[anyone|plyr, "loa_swear_oath", [], "Kneel before me, {s1}, and swear the following oath of fealty to me:^^'I swear homage to you as lawful ruler of the {s41}.'", "loa_swear_oath_2", []],
# [ src/dialogs/ZB01_lords_politics_and_family/anyone_loa_swear_oath_2.py:L1-L3 ] anyone::loa_swear_oath_2->loa_swear_oath_3 [no_conditions] {i pledge homage to you as lawful ruler of the {var}.}
[anyone     , "loa_swear_oath_2", [],  "I pledge homage to you as lawful ruler of the {s41}.", "loa_swear_oath_3", []],
# [ src/dialogs/ZB01_lords_politics_and_family/anyone_loa_swear_oath_3.py:L1-L3 ] anyone::loa_swear_oath_3->loa_swear_oath_4 [no_conditions] {i will remain as your loyal and devoted knight as long as my bre}
[anyone     , "loa_swear_oath_3", [],  "I will remain as your loyal and devoted knight as long as my breath remains.....", "loa_swear_oath_4", []],
