[anyone|plyr, "gm_guild_soldiers", [
   (eq,"$g_talk_troop", black_army_guild_master)
   ],"Raven Captains.", "gm_Raven_Captains", []],
# [ src/dialogs/ZC01_centers_and_economy/anyone_plyr_gm_guild_soldiers_07.py:L1-L5 ] anyone|plyr::gm_guild_soldiers->gm_clansman [eq] {clansman.}
[anyone|plyr, "gm_guild_soldiers", [
   (eq,"$g_talk_troop", boar_clan_guild_master)
   ],"Clansman.", "gm_clansman", []],
# [ src/dialogs/ZC01_centers_and_economy/anyone_plyr_gm_guild_soldiers_08.py:L1-L5 ] anyone|plyr::gm_guild_soldiers->gm_warrior [eq] {warriors.}
