# [ src/dialogs/ZA01_startup_and_dispatch/party_tpl_pt_mercenaries_start.py:L1-L9 ] party_tpl|pt_mercenaries::start->mercenaries_talk [store_party_size|call_script|val_mul] {welcome, sir. you look like somene who could hire some men. we a}
[party_tpl|pt_mercenaries, "start", [
  (store_party_size, reg1, "$g_encountered_party"),
  (call_script, "script_game_get_join_cost", "$g_talk_troop"),
  (val_mul, reg1, reg0),
  (store_relation, ":reln", "fac_manhunters", "fac_player_faction"),
  (ge, ":reln", 0),
  ], "Welcome, sir. You look like somene who could hire some men. We are ready to join you even now for {reg1} denars. Are you interested?", "mercenaries_talk", []],
# [ src/dialogs/ZC02_townsfolk_and_special_npcs/anyone_plyr_mercenaries_talk.py:L1-L6 ] anyone|plyr::mercenaries_talk->mercenaries_no_money [store_troop_gold|lt] {i would hire you, but unfortunatelly, i don't have enough money.}
