[anyone|plyr, "mercenaries_no_money_continue", [
  ], "[Leave]", "close_window", [
  (assign, "$g_leave_encounter", 1),
  ]],
# [ src/dialogs/ZC02_townsfolk_and_special_npcs/anyone_plyr_mercenaries_no_money_continue_02.py:L1-L6 ] anyone|plyr::mercenaries_no_money_continue->close_window [no_conditions] {you're not going anywhere! defend yourself!}
