# [ src/dialogs/ZA02_sod_court_and_strategy/trp_sod_chancellor_chancellor_lord_prelude.py:L1-L56 ] trp_sod_chancellor::chancellor_lord_prelude->chancellor_lord_action [assign|try_for_range|store_troop_faction] {it requires one income producing center per lord, plus an additi}
[trp_sod_chancellor, "chancellor_lord_prelude",
    [
      # include the player
      (assign, ":num_lords", 1),

      # count lords in kingdom
      (try_for_range, ":lord", kingdom_heroes_begin, kingdom_heroes_end),

        (store_troop_faction, ":faction", ":lord"),

        # logic = "troop is a member of our kindom, or he's about to become one" (being one of the reserved and marked as a hero = is about to become one)
        (troop_slot_eq, ":lord", slot_troop_occupation, slto_kingdom_hero),
        (this_or_next|eq, ":faction", "fac_player_supporters_faction"),
        (is_between, ":lord", "trp_reserved_knight_1",  "trp_knight_6_01"),

        (val_add, ":num_lords", 1),
      (try_end),

      # count centers
      (assign, ":num_centers", 0),
      (try_for_range, ":center_no", centers_begin, centers_end),
         (store_faction_of_party, ":center_faction", ":center_no"),
         (neg|party_slot_eq, ":center_no", slot_party_type, spt_castle),  # castles are a liability, not a source of income
         (eq, ":center_faction", "fac_player_supporters_faction"),
         (val_add, ":num_centers", 1),
      (try_end),

      (store_sub, "$territory", ":num_centers", ":num_lords"),
      (try_begin),
        (ge, "$territory", 1),
        (assign, reg1, "$territory"),
        (store_sub, reg0, "$territory", 1),
        (str_store_string, s1, "@We have enough territory to support {reg0?{reg1}:one} more {reg0?Lords:Lord}.  Yes, I think this is a wise choice, my {Lord/Lady}."),
      (else_try),
        (str_store_string, s1, "@We need more territory to recruit additional Lords."),
      (try_end),

      # note: when recruiting a new lord, we ONLY choose from the reserved lords
      (assign, "$lords", 0),
      (try_for_range, ":lord", "trp_reserved_knight_1",  "trp_knight_6_01"),

        # don't choose one that's already active, or that was killed
        (neg|troop_slot_eq, ":lord", slot_troop_occupation, slto_kingdom_hero),
        (neg|troop_slot_eq, ":lord", slot_troop_occupation, slto_dead),

        # add them to our array of possible lords
        (troop_set_slot, "trp_temp_array_a", "$lords", ":lord"),
        (val_add, "$lords", 1),
      (try_end),
    ],
    "It requires one income producing center per lord, plus an additional one for yourself.^^{s1}", "chancellor_lord_action",
    [
    ]
  ],
# [ src/dialogs/ZA02_sod_court_and_strategy/trp_sod_chancellor_plyr_chancellor_lord_action.py:L1-L25 ] trp_sod_chancellor|plyr::chancellor_lord_action->chancellor_lord_recruited [ge|ge] {recruit new lord.}
[trp_sod_chancellor|plyr, "chancellor_lord_action",  [(ge, "$lords", 1), (ge, "$territory", 1)], "Recruit new lord.", "chancellor_lord_recruited",
    [
      # choose a lord at random
      (store_random_in_range, ":roll", 0, "$lords"),
      (troop_get_slot, ":lord", "trp_temp_array_a", ":roll"),

      # intitialize the new lord to be in the player's kingdom with a banner, etc.
      (troop_set_slot, ":lord", slot_troop_change_to_faction, "fac_player_supporters_faction"),
      (troop_set_slot, ":lord", slot_troop_occupation, slto_kingdom_hero),
      (troop_set_slot, ":lord", slot_troop_wealth, recruited_lord_starting_funds),
      # (troop_get_slot, ":selected_banner_spr", "trp_player", slot_troop_banner_scene_prop),
      # (troop_set_slot, ":lord", slot_troop_banner_scene_prop, ":selected_banner_spr"),
      (troop_set_slot, ":lord", slot_troop_original_faction, "fac_player_supporters_faction"),

      # give them an initial relation of 0..10
      (store_random_in_range, ":relation", 0, 11),
      (troop_set_slot, ":lord", slot_troop_player_relation, ":relation"),

      # generate a string to indicate who's joining us
      (call_script, "script_store_troop_name_link", s1, ":lord"),
      (str_store_string, s1, "@{s1} shall be granted titles and honors befitting a Lord."),
    ]
  ],
# [ src/dialogs/ZA02_sod_court_and_strategy/trp_sod_chancellor_chancellor_lord_recruited.py:L1-L3 ] trp_sod_chancellor::chancellor_lord_recruited->chancellor_talk_again [assign|ge|eq] {i apologize, {var}, but there is no one left to heed your call f}
[trp_sod_chancellor, "chancellor_lord_recruited", [(assign, "$temp", 1), (ge, "$territory", 1), (eq, "$lords", 0), (assign, "$temp", 0)], "I apologize, {m'Lord/m'Lady}, but there is no one left to heed your call for another lord.", "chancellor_talk_again", []],
# [ src/dialogs/ZA02_sod_court_and_strategy/trp_sod_chancellor_plyr_chancellor_lord_action_02.py:L1-L3 ] trp_sod_chancellor|plyr::chancellor_lord_action->chancellor_talk_again [eq] {let's look at other topics to make decisions about.}
[trp_sod_chancellor|plyr, "chancellor_lord_action", [(eq, "$temp", 1)], "Let's look at other topics to make decisions about.", "chancellor_talk_again", []],
# [ src/dialogs/ZA02_sod_court_and_strategy/trp_sod_chancellor_chancellor_lord_recruited_02.py:L1-L3 ] trp_sod_chancellor::chancellor_lord_recruited->chancellor_lord_prelude [no_conditions] {it is done. {var}^^wait a day or two, until an announcement is m}
[trp_sod_chancellor, "chancellor_lord_recruited", [], "It is done. {s1}^^Wait a day or two, until an announcement is made, then you will likely want to assign a fief, lest your new Lord run out of money with which to support troops, and hence, your kingdom.", "chancellor_lord_prelude", []],
# [ src/dialogs/ZA02_sod_court_and_strategy/trp_sod_chancellor_chancellor_fiefs_prelude.py:L1-L3 ] trp_sod_chancellor::chancellor_fiefs_prelude->chancellor_fiefs_which [no_conditions] {which fief do you wish to reassign?}
[trp_sod_chancellor, "chancellor_fiefs_prelude", [], "Which fief do you wish to reassign?", "chancellor_fiefs_which", []],
# [ src/dialogs/ZA02_sod_court_and_strategy/trp_sod_chancellor_plyr_repeat_for_parties_chancellor_fiefs_which.py:L1-L49 ] trp_sod_chancellor|plyr|repeat_for_parties::chancellor_fiefs_which->chancellor_fiefs_who [store_repeat_object|is_between|store_faction_of_party] {{var} ({var})}
[trp_sod_chancellor|plyr|repeat_for_parties, "chancellor_fiefs_which",
    [
      (store_repeat_object, ":fief"),
      (is_between, ":fief", "p_town_1", "p_salt_mine"),
      (store_faction_of_party, ":center_faction", ":fief"),
      (eq, ":center_faction", "fac_player_supporters_faction"),
      (str_store_party_name, s1, ":fief"),
      (try_begin),
        (party_slot_eq, ":fief", slot_party_type, spt_village),
        (party_get_slot, ":bound_to", ":fief", slot_village_bound_center),
        (str_store_party_name, s2, ":bound_to"),
        (str_store_string, s1, "@Village of {s1} bound to {s2}"),
      (else_try),
        (str_clear, s3),
        (assign, ":count", 0),
        (try_for_range, ":village", villages_begin, villages_end),
          (party_slot_eq, ":village", slot_village_bound_center, ":fief"),
          (str_store_party_name, s2, ":village"),
          (val_add, ":count", 1),
          (try_begin),
            (eq, ":count", 1),
            (str_store_string_reg, s3, s2),
          (else_try),
            (str_store_string, s3, "@{s3},{s2}"),
          (try_end),
        (try_end),
        (try_begin),
          (party_slot_eq, ":fief", slot_party_type, spt_town),
          (str_store_string, s1, "@Town of {s1}+{s3}"),
        (else_try),
          (str_store_string, s1, "@{s1}+{s3}"),
        (try_end),
      (try_end),
      (party_get_slot, ":lord", ":fief", slot_town_lord),
      (call_script, "script_store_troop_name", s2, ":lord"),
      (call_script, "script_troop_get_player_relation", ":lord"),
      (call_script, "script_describe_troop_relation", s3, reg0),
      (call_script, "script_get_number_of_hero_centers", ":lord"),
      (try_begin),
        (eq, ":lord", "trp_player"),
        (str_store_string, s2, "@{s2}, {reg0?{reg0}:no} fiefs"),
      (else_try),
        (str_store_string, s2, "@{s2}, {reg0?{reg0}:no} fiefs, {s3}"),
      (try_end),
    ],
    "{s1} ({s2})", "chancellor_fiefs_who", [(store_repeat_object, "$assign_fief")]
  ],
# [ src/dialogs/ZA02_sod_court_and_strategy/trp_sod_chancellor_plyr_chancellor_fiefs_which.py:L1-L3 ] trp_sod_chancellor|plyr::chancellor_fiefs_which->chancellor_talk_again [no_conditions] {let's look at other topics to make decisions about.}
[trp_sod_chancellor|plyr, "chancellor_fiefs_which", [], "Let's look at other topics to make decisions about.", "chancellor_talk_again", []],
# [ src/dialogs/ZA02_sod_court_and_strategy/trp_sod_chancellor_chancellor_fiefs_who.py:L1-L37 ] trp_sod_chancellor::chancellor_fiefs_who->chancellor_fiefs_reassign [party_get_slot|str_store_party_name|try_begin] {{var} ({var}). who shall be your vassal to manage these lands?}
[trp_sod_chancellor, "chancellor_fiefs_who",
    [
      (party_get_slot, ":lord", "$assign_fief", slot_town_lord),

      (str_store_party_name, s1, "$assign_fief"),
      (try_begin),
        (party_slot_eq, "$assign_fief", slot_party_type, spt_village),
        (party_get_slot, ":bound_to", "$assign_fief", slot_village_bound_center),
        (str_store_party_name, s2, ":bound_to"),
        (str_store_string, s1, "@The village of {s1} bound to {s2}"),
      (else_try),
        (str_clear, s3),
        (assign, ":count", 0),
        (try_for_range, ":village", villages_begin, villages_end),
          (party_slot_eq, ":village", slot_village_bound_center, "$assign_fief"),
          (str_store_party_name, s2, ":village"),
          (val_add, ":count", 1),
          (try_begin),
            (eq, ":count", 1),
            (str_store_string_reg, s3, s2),
          (else_try),
            (str_store_string, s3, "@{s3},{s2}"),
          (try_end),
        (try_end),
        (try_begin),
          (party_slot_eq, "$assign_fief", slot_party_type, spt_town),
          (str_store_string, s1, "@Town of {s1}+{s3}"),
        (else_try),
          (str_store_string, s1, "@{s1}+{s3}"),
        (try_end),
      (try_end),

      (call_script, "script_store_troop_name", s2, ":lord"),
    ],
    "{s1} ({s2}). Who shall be your vassal to manage these lands?", "chancellor_fiefs_reassign", []],
# [ src/dialogs/ZA02_sod_court_and_strategy/trp_sod_chancellor_plyr_chancellor_fiefs_reassign.py:L1-L27 ] trp_sod_chancellor|plyr::chancellor_fiefs_reassign->chancellor_fiefs_prelude [neg|party_slot_eq] {i want it for myself.}
[trp_sod_chancellor|plyr, "chancellor_fiefs_reassign",
    [
      # don't include ourselves as an option if we already own it
      (neg|party_slot_eq, "$assign_fief", slot_town_lord, "trp_player"),
    ],
    "I want it for Myself.", "chancellor_fiefs_prelude",
    [
      # adjust relations for stripping them of their fief
      (try_begin),
        # take this center away from the old lord
        (party_get_slot, ":old_lord", "$assign_fief", slot_town_lord),
        (gt, ":old_lord", "trp_player"),
        (call_script, "script_change_player_relation_with_troop", ":old_lord", -10),
        # take each of the bound villages away from their lords
        (try_for_range, ":village", villages_begin, villages_end),
          (party_slot_eq, ":village", slot_village_bound_center, "$assign_fief"),
          (party_get_slot, ":old_lord", ":village", slot_town_lord),
          (gt, ":old_lord", "trp_player"),
          (call_script, "script_change_player_relation_with_troop", ":old_lord", -10),
        (try_end),
      (try_end),
      # give it and all of its bound villages to the player
      (call_script, "script_give_center_to_lord", "$assign_fief",  "trp_player", 0),
    ]
  ],
# [ src/dialogs/ZA02_sod_court_and_strategy/trp_sod_chancellor_plyr_repeat_for_troops_chancellor_fiefs_reassign.py:L1-L62 ]
[trp_sod_chancellor|plyr|repeat_for_troops, "chancellor_fiefs_reassign",
    [
      (store_repeat_object, ":new_lord"),

      # only relevant to our lords
      (is_between, ":new_lord", kingdom_heroes_begin, kingdom_heroes_end),
      (troop_slot_eq, ":new_lord", slot_troop_occupation, slto_kingdom_hero),

      # don't allow us to assign a fief to a new_lord that hasn't officially joined us yet!
      (store_troop_faction, ":faction_no", ":new_lord"),
      (eq, ":faction_no", "fac_player_supporters_faction"),

      # don't give the player the option to give it to the lord that already owns it (pointless, one less menu to scroll through)
      (neg|party_slot_eq, "$assign_fief", slot_town_lord, ":new_lord"),

      # generate the talk text
#      (str_store_party_name, s1, "$assign_fief"),
#      (try_begin),
#        (party_slot_eq, "$assign_fief", slot_party_type, spt_village),
#        (party_get_slot, ":bound_to", "$assign_fief", slot_village_bound_center),
#        (str_store_party_name, s2, ":bound_to"),
#        (str_store_string, s1, "@The village of {s1} bound to {s2}"),
#      (try_end),

      (call_script, "script_store_troop_name", s2, ":new_lord"),
      (call_script, "script_troop_get_player_relation", ":new_lord"),
      (call_script, "script_describe_troop_relation", s3, reg0),
      (call_script, "script_get_number_of_hero_centers", ":new_lord"),
    ],
#    "Assign {s1} to {s2} ({reg0?{reg0}:no} fiefs, {s3})", "chancellor_fiefs_prelude",
    "Assign to {s2} ({reg0?{reg0}:no} fiefs, {s3})", "chancellor_fiefs_prelude",
    [
      (store_repeat_object, "$temp_lord"),

      (assign, ":count", 1),
      (try_begin),
        # adjust relations for stripping the previous owner of their fief
        (party_get_slot, ":old_lord", "$assign_fief", slot_town_lord),
        (gt, ":old_lord", "trp_player"),
        (call_script, "script_change_player_relation_with_troop", ":old_lord", -10),
        # take each of the bound villages away from their lords (and determine the count of centers that we're giving to this lord in total)
        (try_for_range, ":village", villages_begin, villages_end),
          (party_slot_eq, ":village", slot_village_bound_center, "$assign_fief"),
          (party_get_slot, ":old_lord", ":village", slot_town_lord),
          (gt, ":old_lord", "trp_player"),
          (neq, ":old_lord", "$temp_lord"),
          (call_script, "script_change_player_relation_with_troop", ":old_lord", -10),
          (val_add, ":count", 1),
        (try_end),
      (try_end),

      # give it to selected lord (and all bound villages)
      (call_script, "script_give_center_to_lord", "$assign_fief",  "$temp_lord", 0),

      # positive relation for giving new owner the fief
      (val_mul, ":count", 10),
      (call_script, "script_change_player_relation_with_troop", "$temp_lord", ":count"),
	  (call_script, "script_update_titles"),
    ]
  ],
# [ src/dialogs/ZA02_sod_court_and_strategy/trp_sod_chancellor_plyr_chancellor_fiefs_reassign_02.py:L1-L3 ] trp_sod_chancellor|plyr::chancellor_fiefs_reassign->chancellor_talk_again [no_conditions] {nevermind.}
[trp_sod_chancellor|plyr, "chancellor_fiefs_reassign", [], "Nevermind.", "chancellor_talk_again", []],
