[trp_sod_chancellor|plyr, "chancellor_war", [], "To the Kingdom of Swadia.", "chancellor_ok", [(call_script, "script_diplomacy_start_war_between_kingdoms", "fac_player_supporters_faction", "fac_kingdom_1", 1),]],
