# [ src/dialogs/ZB01_lords_politics_and_family/anyone_plyr_defeat_lord_answer.py:L1-L5 ] anyone|plyr::defeat_lord_answer->cc_humilitae_1 [troop_slot_eq] {remember what i promised about a pile of horse dung ? well, i li}
[anyone|plyr, "defeat_lord_answer", [
	(troop_slot_eq, "$g_talk_troop", slot_troop_centurion_personality, slcp_crusader),
  ], "Remember what I promised about a pile of horse dung ? Well, I like to keep my promises...", "cc_humilitae_1", [] ],
# [ src/dialogs/ZZ99_misc_dialogs/anyone_cc_humilitae_1.py:L1-L4 ] anyone::cc_humilitae_1->cc_humilitae_2 [no_conditions] {don't you dare !}
[anyone, "cc_humilitae_1", [
  ], "Don't you DARE !", "cc_humilitae_2", [] ],
# [ src/dialogs/ZZ99_misc_dialogs/anyone_plyr_cc_humilitae_2.py:L1-L4 ] anyone|plyr::cc_humilitae_2->cc_humilitae_3 [no_conditions] {yes i dare. soldiers, you know what to do !}
[anyone|plyr, "cc_humilitae_2", [
  ], "Yes I dare. Soldiers, you know what to do !", "cc_humilitae_3", [(call_script, "script_change_player_honor", -20)] ],
# [ src/dialogs/ZZ99_misc_dialogs/anyone_cc_humilitae_3.py:L1-L4 ] anyone::cc_humilitae_3->cc_humilitae_4 [no_conditions] {(fortunately enough, there is a recently abandoned farmhouse nea}
[anyone, "cc_humilitae_3", [
  ], "(Fortunately enough, there is a recently abandoned farmhouse nearby, with a great intact pile of horse dung in front of it. However, {s29} stuggles so hard that your men ultimately decide to tie him up and put him into one of the smaller catapults to lauch him. However, despite all the careful calculations, the Centurion DOES end up in the dung pile, rather than getting smashed against the front wall of the house like your men were hoping.)", "cc_humilitae_4", [] ],
# [ src/dialogs/ZZ99_misc_dialogs/anyone_cc_humilitae_4.py:L1-L4 ] anyone::cc_humilitae_4->cc_humilitae_5 [no_conditions] {(as {var} manages to crawl out practically unharmed, covered wit}
[anyone, "cc_humilitae_4", [
  ], "(As {s29} manages to crawl out practically unharmed, covered with the disgusting material, he shouts curses about how he'll flay you alive, but can't finish before your soldiers start throwing pebbles and rotten fruits at him. {s29} runs as fast as his legs allow him, burdened by shame and stinking dung. Some soldiers ask you whether they should follow and kill him, but you turn them down. Let the coward live. Hearing your weary army laughing so heartily is a great prize in itself. Still, you can't stop yourself from shouting one more insult towards the Centurion...)", "cc_humilitae_5", [] ],
# [ src/dialogs/ZZ99_misc_dialogs/anyone_plyr_cc_humilitae_5.py:L1-L4 ] anyone|plyr::cc_humilitae_5->close_window [no_conditions] {yes ! scurry away like the frightened mice you are ! soon i will}
[anyone|plyr, "cc_humilitae_5", [
  ], "Yes ! Scurry away like the frightened mice you are ! Soon I will come to claim you all !", "close_window", [] ],
# [ src/dialogs/ZB01_lords_politics_and_family/anyone_plyr_defeat_lord_answer_02.py:L1-L48 ] anyone|plyr::defeat_lord_answer->defeat_lord_answer_1 [neg|troop_slot_eq|try_begin|troop_slot_eq] {{var}}
[anyone|plyr, "defeat_lord_answer", [
	(neg|troop_slot_eq, "$g_talk_troop", slot_troop_centurion_personality, slcp_nihilistic),
	(try_begin),
		(troop_slot_eq, "$g_talk_troop", slot_troop_centurion_personality, slcp_sane),
		(str_store_string, s0, "@Don't you worry now. I'll put you into a nice cell."),
	(else_try),
		(troop_slot_eq, "$g_talk_troop", slot_troop_centurion_personality, slcp_respectful),
		(str_store_string, s0, "@For the damage you caused to my people, I will take you into prison."),
	(else_try),
		(troop_slot_eq, "$g_talk_troop", slot_troop_centurion_personality, slcp_imperialist),
		(str_store_string, s0, "@Now it is your turn to bear the shame of defeat. I will take you to prison."),
	(else_try),
		(troop_slot_eq, "$g_talk_troop", slot_troop_centurion_personality, slcp_capitalist),
		(str_store_string, s0, "@A fitting end for a parasite like you. It's time to put you where you belong - a prison cell."),
	(else_try),
		(troop_slot_eq, "$g_talk_troop", slot_troop_centurion_personality, slcp_racist),
		(str_store_string, s0, "@I'll take you prisoner. Soldiers, chain him !"),
	(else_try),
		(troop_slot_eq, "$g_talk_troop", slot_troop_centurion_personality, slcp_crusader),
		(str_store_string, s0, "@I figure you can't do much harm imprisoned, so that's what I'm going to do to you."),
	(else_try),
		(troop_slot_eq, "$g_talk_troop", slot_troop_centurion_personality, slcp_liberator),
		(str_store_string, s0, "@There are fates worse than death, Centurion. You'll learn that in my dungeon soon enough."),
	(else_try),
		is_legate,
		(str_store_string, s0, "@For your crimes committed against the {s31}, I place you under arrest."),
	(else_try),
		(str_store_string, s0, "@You are my prisoner now."),
	(try_end),
  ],
   "{s0}", "defeat_lord_answer_1",
   [
	(try_begin),
	 (neg|troop_slot_eq, "$g_talk_troop", slot_troop_centurion_personality, slcp_capitalist),
     (troop_set_slot, "$g_talk_troop", slot_troop_prisoner_of_party, "p_main_party"),
     (party_force_add_prisoners, "p_main_party", "$g_talk_troop", 1), #take prisoner
	 (try_begin),
		(neg|troop_slot_eq, "$g_talk_troop", slot_troop_centurion_personality, slcp_sane),
		(neq, "$g_talk_troop", "trp_kingdom_6_lord"),
		(call_script, "script_change_player_relation_with_troop", "$g_talk_troop", -10),
	 (try_end),
     (call_script, "script_change_player_relation_with_faction_ex", "$g_talk_troop_faction", -3),
     (call_script, "script_event_hero_taken_prisoner_by_player", "$g_talk_troop"),
     (call_script, "script_add_log_entry", logent_lord_captured_by_player, "trp_player",  -1, "$g_talk_troop", "$g_talk_troop_faction"),
    (try_end),
	 ]],
